 1	final class BinarySearch {
 2	    private static final int DEMO_TARGET = 10;
 3	    private static final String FOUND_MESSAGE_PREFIX = "Element is present at index ";
 4	    private static final String NOT_FOUND_MESSAGE = "Element is not present in array";
 5	
 6	    private BinarySearch() {
 7	    }
 8	
 9	    static int binarySearch(int[] values, int target) {
10	        return indexOf(values, target);
11	    }
12	
13	    static int indexOf(int[] values, int target) {
14	        return search(values, target).indexOrNotFound();
15	    }
16	
17	    static SearchResult search(int[] values, int target) {
18	        requireValues(values);
19	
20	        int low = 0;
21	        int high = values.length - 1;
22	
23	        while (low <= high) {
24	            int middle = midpoint(low, high);
25	            int currentValue = values[middle];
26	            int comparison = Integer.compare(currentValue, target);
27	
28	            if (comparison == 0) {
29	                return SearchResult.found(middle);
30	            }
31	
32	            if (comparison < 0) {
33	                low = middle + 1;
34	            } else {
35	                high = middle - 1;
36	            }
37	        }
38	
39	        return SearchResult.notFound();
40	    }
41	
42	    public static void main(String[] args) {
43	        System.out.println(runDemo());
44	    }
45	
46	    private static String runDemo() {
47	        int[] values = { 2, 3, 4, 10, 40 };
